<?php $assignment=$account?st_staff_assignment_state($u,(int)$account['id']):['event_scope'=>'assigned','event_ids'=>[]]; ?>
<fieldset class="permission-fields wide"><legend>Event workspaces</legend><input type="hidden" name="event_scope_present" value="1"><p class="help">Permissions determine actions. Event assignments determine which records this person can access. No selected events means no event access.</p><label class="check-field"><input type="checkbox" name="event_scope" value="all" <?= $assignment['event_scope']==='all'?'checked':'' ?>>Festival-wide access, including all future events</label><div class="scope-grid"><?php foreach(cms_records('event',false) as $ev): ?><label class="check-field"><input type="checkbox" name="event_ids[]" value="<?= (int)$ev['id'] ?>" <?= in_array((int)$ev['id'],$assignment['event_ids'],true)?'checked':'' ?>><?= e($ev['title']) ?><small><?= e($ev['status']) ?></small></label><?php endforeach; ?></div><p class="help">Assign coordinators and gate volunteers to their own events. Festival-wide access is for central administration.</p></fieldset>
